import os
import re
import pytesseract
from PIL import Image
import openpyxl


def norm(s):
    """Strip all non-alphanumeric characters, uppercase."""
    return re.sub(r'[^A-Z0-9]', '', s.upper())


PRIORITY_KEYWORDS = [
    ['GRANDTOTAL'],
    ['TOTALRM'],
    ['TOTALAMOUNT'],
    ['TOTALDUE', 'AMOUNTDUE', 'BALANCEDUE', 'NETTTOTAL', 'NETTOTAL',
     'TOTAL', 'AMOUNT'],
]


def ocr(path, psm=6, scale=2):
    img = Image.open(path)
    if scale != 1:
        img = img.resize((img.width * scale, img.height * scale))
    return pytesseract.image_to_string(img, config=f'--psm {psm}')


def clean_number_str(s):
    s = s.replace(' ', '')
    if ',' in s and '.' in s:
        s = s.replace(',', '')
    elif ',' in s and '.' not in s:
        s = s.replace(',', '.')
    try:
        return f"{float(s):.2f}"
    except ValueError:
        return None


def extract_amount_from_line(line):
    # ". u00" / ". l00" -> ".00"  (OCR letter inside decimal)
    cleaned = re.sub(r'(?<=\d)\.\s*[a-zA-Z]+(?=\d)', '.', line)
    # Colon as decimal separator: "92:80" -> "92.80"
    cleaned = re.sub(r'(?<=\d):(?=\d{2}(?!\d))', '.', cleaned)
    # Space inside decimal: "85. 54" -> "85.54"
    cleaned = re.sub(r'(\d)\.\s+(\d)', r'\1.\2', cleaned)
    # XX.XX or X,XXX.XX not followed by another digit
    matches = re.findall(r'\d[\d,]*\.\d{2}(?!\d)', cleaned)
    if matches:
        return clean_number_str(matches[-1])
    matches = re.findall(r'(?<!\d)\d+,\d{2}(?!\d)', cleaned)
    if matches:
        return clean_number_str(matches[-1])
    return None


# Strict exclusion: any line containing these (normalized) is skipped.
EXCLUSION_SUBSTRINGS = ['SUBTOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CASHTENDERED']


def is_excluded(nline):
    for ex in EXCLUSION_SUBSTRINGS:
        if ex in nline:
            return True
    # CHANGE but not EXCHANGE.
    if re.search(r'(?<!EX)CHANGE', nline):
        return True
    return False


def extract_total(text):
    lines = text.split('\n')
    normalized = [norm(l) for l in lines]

    for kw_level in PRIORITY_KEYWORDS:
        matches = []
        for i, line in enumerate(lines):
            nline = normalized[i]
            if not nline:
                continue
            if is_excluded(nline):
                continue
            matched_kw = next((kw for kw in kw_level if kw in nline), None)
            if matched_kw is None:
                continue
            amt = extract_amount_from_line(line)
            if amt is None:
                # Only fall back when the current line is essentially just the
                # keyword and the next line looks like a bare number.
                extra = len(nline) - len(matched_kw)
                if extra <= 1 and i + 1 < len(lines):
                    nxt = lines[i + 1].strip()
                    if re.match(r'^[\s\-\$RMm0-9,.]+$', nxt) and re.search(r'\d', nxt):
                        amt = extract_amount_from_line(nxt)
            if amt is not None:
                matches.append(amt)
        if matches:
            return matches[-1]
    return None


def extract_date(text):
    for m in re.finditer(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})(?!\d)', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    for m in re.finditer(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y += 2000
        if 1 <= d <= 31 and 1 <= mo <= 12:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    return None


def process_file(path):
    # Primary pass: PSM 6 at 2x scale works best for most receipts.
    text = ocr(path, psm=6, scale=2)
    date = extract_date(text)
    total = extract_total(text)

    fallbacks = [(3, 1), (6, 1), (3, 2)]
    for psm, scale in fallbacks:
        if date is not None and total is not None:
            break
        fb_text = ocr(path, psm=psm, scale=scale)
        if date is None:
            date = extract_date(fb_text)
        if total is None:
            total = extract_total(fb_text)
    return date, total


def process(img_dir):
    results = []
    for fn in sorted(os.listdir(img_dir)):
        if not fn.lower().endswith(('.jpg', '.jpeg', '.png')):
            continue
        date, total = process_file(os.path.join(img_dir, fn))
        results.append((fn, date, total))
    return results


def write_xlsx(results, path):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, date, total in results:
        ws.append([fn, date, total])
    wb.save(path)


if __name__ == "__main__":
    results = process("/app/workspace/dataset/img")
    for r in results:
        print(r)
    write_xlsx(results, "/app/workspace/stat_ocr.xlsx")
