        mo = MONTH_NAMES[mo_s]
        y = int(m.group(3))
        if y < 100:
            y += 2000
        if 1 <= d <= 31 and 2000 <= y <= 2099:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    return None


