import os
import re
import pytesseract
from PIL import Image
import openpyxl

EXCLUSIONS = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST',
              'DISCOUNT', 'CHANGE', 'CASH TENDERED']

PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL',
     'TOTAL', 'AMOUNT'],
