def ocr(path, psm=None):
    img = Image.open(path)
    cfg = f'--psm {psm}' if psm is not None else ''
    return pytesseract.image_to_string(img, config=cfg)


def normalize_number(s):
    s = s.replace(' ', '')
    if ',' in s and '.' in s:
        s = s.replace(',', '')
    elif ',' in s and '.' not in s:
        s = s.replace(',', '.')
    try:
        return f"{float(s):.2f}"
    except ValueError:
        return None


def extract_amount_from_line(line):
    # Merge split decimals like "85. 54" -> "85.54"
    cleaned = re.sub(r'(\d)\.\s+(\d)', r'\1.\2', line)
    # Primary: XX.XX or X,XXX.XX
    matches = re.findall(r'\d[\d,]*\.\d{2}(?!\d)', cleaned)
    if matches:
        return normalize_number(matches[-1])
    # Fallback: XX,XX (comma as decimal)
    matches = re.findall(r'(?<!\d)\d+,\d{2}(?!\d)', cleaned)
    if matches:
        return normalize_number(matches[-1])
    return None


def extract_total(text):
    lines = text.split('\n')
    for kw_level in PRIORITY_KEYWORDS:
        for i, line in enumerate(lines):
            upper = line.upper()
            if any(ex in upper for ex in EXCLUSIONS):
                continue
            if any(kw in upper for kw in kw_level):
                amt = extract_amount_from_line(line)
                if amt is None and i + 1 < len(lines):
                    amt = extract_amount_from_line(lines[i + 1])
                if amt is not None:
                    return amt
    return None


MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}


def extract_date(text):
    # DD/MM/YYYY or DD-MM-YYYY
    for m in re.finditer(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})(?!\d)', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
