    normalized = [norm(l) for l in lines]
    # Cut off at GST SUMMARY / TAX SUMMARY marker.
    cutoff = len(lines)
    for i, nline in enumerate(normalized):
        if 'GSTSUMMARY' in nline or 'TAXSUMMARY' in nline:
            cutoff = i
            break
