EXCLUSIONS = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST',
              'DISCOUNT', 'CHANGE', 'CASH TENDERED']

PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL',
     'TOTAL', 'AMOUNT'],
]


def ocr(path, psm=None):
    img = Image.open(path)
    cfg = f'--psm {psm}' if psm is not None else ''
    return pytesseract.image_to_string(img, config=cfg)


def normalize_number(s):
    s = s.replace(' ', '')
    if ',' in s and '.' in s:
        s = s.replace(',', '')
    elif ',' in s and '.' not in s:
        s = s.replace(',', '.')
    try:
        return f"{float(s):.2f}"
    except ValueError:
        return None


def extract_amount_from_line(line):
    # Merge split decimals like "85. 54" -> "85.54"
    cleaned = re.sub(r'(\d)\.\s+(\d)', r'\1.\2', line)
    # Primary: XX.XX or X,XXX.XX
    matches = re.findall(r'\d[\d,]*\.\d{2}(?!\d)', cleaned)
    if matches:
        return normalize_number(matches[-1])
    # Fallback: XX,XX (comma as decimal)
    matches = re.findall(r'(?<!\d)\d+,\d{2}(?!\d)', cleaned)
    if matches:
        return normalize_number(matches[-1])
    return None


def extract_total(text):
    lines = text.split('\n')
    for kw_level in PRIORITY_KEYWORDS:
        for i, line in enumerate(lines):
            upper = line.upper()
            if any(ex in upper for ex in EXCLUSIONS):
                continue
            if any(kw in upper for kw in kw_level):
                amt = extract_amount_from_line(line)
                if amt is None and i + 1 < len(lines):
                    amt = extract_amount_from_line(lines[i + 1])
                if amt is not None:
                    return amt
    return None


MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12,
}


def extract_date(text):
    # DD/MM/YYYY or DD-MM-YYYY
    for m in re.finditer(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})(?!\d)', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    # DD/MM/YY
    for m in re.finditer(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y += 2000
        if 1 <= d <= 31 and 1 <= mo <= 12:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    # DD MMM YYYY or similar textual month
    pat = r'(?<!\d)(\d{1,2})[\s\-/]+([A-Za-z]{3,9})[\s\-/]+(\d{2,4})(?!\d)'
    for m in re.finditer(pat, text):
        d = int(m.group(1))
        mo_s = m.group(2)[:3].upper()
        if mo_s not in MONTH_NAMES:
            continue
        mo = MONTH_NAMES[mo_s]
        y = int(m.group(3))
        if y < 100:
            y += 2000
        if 1 <= d <= 31 and 2000 <= y <= 2099:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    return None


def process(img_dir):
    results = []
    for fn in sorted(os.listdir(img_dir)):
        if not fn.lower().endswith(('.jpg', '.jpeg', '.png')):
            continue
        text = ocr(os.path.join(img_dir, fn))
        date = extract_date(text)
        total = extract_total(text)
        results.append((fn, date, total))
    return results


def write_xlsx(results, path):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, date, total in results:
        ws.append([fn, date, total])
    wb.save(path)


