import openpyxl


def norm(s):
    return re.sub(r'[^A-Z0-9]', '', s.upper())


# Normalized form: strip all non-alphanumeric and uppercase.
# Priority levels, from most to least specific.
PRIORITY_KEYWORDS = [
    ['GRANDTOTAL'],
    ['TOTALRM'],
    ['TOTALAMOUNT'],
    ['TOTALDUE', 'AMOUNTDUE', 'BALANCEDUE', 'NETTTOTAL', 'NETTOTAL',
