    s = s.replace(' ', '')
    if ',' in s and '.' in s:
        s = s.replace(',', '')
    elif ',' in s and '.' not in s:
        s = s.replace(',', '.')
    try:
        return f"{float(s):.2f}"
    except ValueError:
        return None


def extract_amount_from_line(line):
    # OCR artifact: ". u00" or ". l00" -> ".00"
    cleaned = re.sub(r'(?<=\d)\.\s*[a-zA-Z]+(?=\d)', '.', line)
    # OCR artifact: colon-as-decimal "92:80" -> "92.80"
    cleaned = re.sub(r'(?<=\d):(?=\d{2}(?!\d))', '.', cleaned)
    # OCR artifact: "85. 54" -> "85.54"
    cleaned = re.sub(r'(\d)\.\s+(\d)', r'\1.\2', cleaned)
    # Primary: XX.XX or X,XXX.XX (not followed by digit)
    matches = re.findall(r'\d[\d,]*\.\d{2}(?!\d)', cleaned)
    if matches:
        return clean_number_str(matches[-1])
    # Fallback: XX,XX (comma as decimal)
    matches = re.findall(r'(?<!\d)\d+,\d{2}(?!\d)', cleaned)
    if matches:
        return clean_number_str(matches[-1])
    return None


def is_excluded(nline):
    """Check if a normalized line should be excluded."""
    # Section markers appear elsewhere; here we handle per-line exclusions.
    if 'SUBTOTAL' in nline:
        return True
    if 'DISCOUNT' in nline:
        return True
    if 'CASHTENDERED' in nline:
        return True
    # Lines starting with GST/TAX/SST (as primary label)
    m = re.match(r'^(GST|TAX|SST)', nline)
    if m:
        return True
    # Patterns like "TOTAL GST" (total of GST, not total incl GST)
    if 'TOTALGST' in nline or 'TOTALTAX' in nline or 'TOTALSST' in nline:
        return True
    if 'GSTTOTAL' in nline or 'TAXTOTAL' in nline or 'SSTTOTAL' in nline:
        return True
    # Change (but not "Exchange"): standalone word
    if re.search(r'(?<!EX)CHANGE', nline):
        return True
    return False


def extract_total(text):
    lines = text.split('\n')
    normalized = [norm(l) for l in lines]
    # Cut off at GST SUMMARY / TAX SUMMARY marker.
    cutoff = len(lines)
    for i, nline in enumerate(normalized):
        if 'GSTSUMMARY' in nline or 'TAXSUMMARY' in nline:
            cutoff = i
            break
    lines = lines[:cutoff]
    normalized = normalized[:cutoff]

    for kw_level in PRIORITY_KEYWORDS:
        matches = []
        for i, line in enumerate(lines):
            nline = normalized[i]
            if not nline:
                continue
            if is_excluded(nline):
                continue
            matched_kw = next((kw for kw in kw_level if kw in nline), None)
            if matched_kw is None:
                continue
            amt = extract_amount_from_line(line)
            if amt is None:
                extra = len(nline) - len(matched_kw)
                if extra <= 3 and i + 1 < len(lines):
                    amt = extract_amount_from_line(lines[i + 1])
            if amt is not None:
                matches.append(amt)
        if matches:
            return matches[-1]
    return None


def extract_date(text):
    # DD/MM/YYYY or DD-MM-YYYY
    for m in re.finditer(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})(?!\d)', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    # DD/MM/YY
    for m in re.finditer(r'(?<!\d)(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)', text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        y += 2000
        if 1 <= d <= 31 and 1 <= mo <= 12:
            return f"{y:04d}-{mo:02d}-{d:02d}"
    return None


def process_file(path):
    text = ocr(path, psm=3)
    date = extract_date(text)
    total = extract_total(text)
    if date is None or total is None:
        text6 = ocr(path, psm=6)
        if date is None:
            date = extract_date(text6)
        if total is None:
            total = extract_total(text6)
